// A calculator with + - * / and brackets, built as a recursive-descent parser.
import Foundation
setvbuf(stdout, nil, _IONBF, 0)

enum CalcError: Error { case unexpected(String), divideByZero }

struct Parser {
    var tokens: [String]
    var pos = 0

    init(_ text: String) {
        var out: [String] = []
        var number = ""
        for ch in text where ch != " " {
            if ch.isNumber || ch == "." { number.append(ch) } else {
                if !number.isEmpty { out.append(number); number = "" }
                out.append(String(ch))
            }
        }
        if !number.isEmpty { out.append(number) }
        tokens = out
    }

    var peek: String? { pos < tokens.count ? tokens[pos] : nil }
    mutating func next() -> String? { defer { pos += 1 }; return peek }

    mutating func factor() throws -> Double {
        guard let t = next() else { throw CalcError.unexpected("end of sum") }
        if t == "(" {
            let v = try expression()
            guard next() == ")" else { throw CalcError.unexpected("missing )") }
            return v
        }
        if t == "-" { return -(try factor()) }
        guard let v = Double(t) else { throw CalcError.unexpected(t) }
        return v
    }

    mutating func term() throws -> Double {
        var v = try factor()
        while let op = peek, op == "*" || op == "/" {
            pos += 1
            let right = try factor()
            if op == "/" && right == 0 { throw CalcError.divideByZero }
            v = op == "*" ? v * right : v / right
        }
        return v
    }

    mutating func expression() throws -> Double {
        var v = try term()
        while let op = peek, op == "+" || op == "-" {
            pos += 1
            let right = try term()
            v = op == "+" ? v + right : v - right
        }
        return v
    }
}

func calculate(_ text: String) -> String {
    var parser = Parser(text)
    do {
        let v = try parser.expression()
        if let extra = parser.peek { throw CalcError.unexpected(extra) }
        return v == v.rounded() && abs(v) < 1e15 ? String(Int(v)) : String(v)
    } catch CalcError.divideByZero {
        return "can't divide by zero"
    } catch CalcError.unexpected(let what) {
        return "didn't expect \(what)"
    } catch {
        return "error"
    }
}

for sample in ["3 * (4 + 5)", "10 / 4 - 1", "2 * (3"] { print("\(sample) = \(calculate(sample))") }
print("Type a sum (or q to quit).")
while true {
    print("> ", terminator: "")
    guard let line = readLine(), line != "q", !line.isEmpty else { break }
    print("= \(calculate(line))")
}

