enum Unit: Character, CaseIterable {
    case celsius = "c", fahrenheit = "f", kelvin = "k"

    func toCelsius(_ v: Double) -> Double {
        switch self {
        case .celsius: return v
        case .fahrenheit: return (v - 32) * 5 / 9
        case .kelvin: return v - 273.15
        }
    }

    func fromCelsius(_ c: Double) -> Double {
        switch self {
        case .celsius: return c
        case .fahrenheit: return c * 9 / 5 + 32
        case .kelvin: return c + 273.15
        }
    }
}

func convert(_ text: String) -> String {
    let t = text.lowercased()
    guard let last = t.last, let unit = Unit(rawValue: last), let value = Double(t.dropLast()) else {
        return "Use a number followed by c, f or k (like 72f)."
    }
    let c = unit.toCelsius(value)
    return Unit.allCases.map { String(format: "%.1f°", $0.fromCelsius(c)) + String($0.rawValue).uppercased() }.joined(separator: "  ")
}

for sample in ["72f", "21c", "300k"] { print("\(sample) → \(convert(sample))") }
print("Type a temperature (or q to quit).")
while true {
    print("> ", terminator: "")
    guard let line = readLine()?.trimmingCharacters(in: .whitespaces), line != "q", !line.isEmpty else { break }
    print(convert(line))
}

