func askNumber(_ prompt: String, default fallback: Double) -> Double {
    print("\(prompt) [\(fallback)]: ", terminator: "")
    guard let line = readLine(), let value = Double(line.trimmingCharacters(in: .whitespaces)) else { return fallback }
    return value
}

func money(_ v: Double) -> String { String(format: "$%.2f", v) }

let bill = askNumber("Bill total", default: 50)
