let tip = bill * tipPercent / 100
let total = bill + tip

print("\nTip:        \(money(tip))")
print("Total:      \(money(total))")
print("Per person: \(money(total / Double(people)))")
print("\nOther tips:")
for percent in [10.0, 15, 20, 25] {
    print("  \(Int(percent))% → \(money(bill * (1 + percent / 100) / Double(people))) each")
}

