func bar(_ done: Int, of total: Int, width: Int = 20) -> String {
    let filled = total == 0 ? width : width * done / total
    return String(repeating: "█", count: filled) + String(repeating: "░", count: width - filled)
}

func countdown(from seconds: Int, tick: TimeInterval = 1) {
    for left in stride(from: seconds, to: 0, by: -1) {
        print("\(bar(seconds - left, of: seconds)) \(left)s left")
        Thread.sleep(forTimeInterval: tick)
    }
    print("\(bar(1, of: 1)) Time's up! ⏰")
}

print("Seconds to count down [5]: ", terminator: "")
if let line = readLine() {
    countdown(from: Int(line.trimmingCharacters(in: .whitespaces)) ?? 5)
} else {
    countdown(from: 3, tick: 0.2)
}

