enum Move: String, CaseIterable {
    case rock, paper, scissors

    var beats: Move {
        switch self {
        case .rock: return .scissors
        case .paper: return .rock
        case .scissors: return .paper
        }
    }

    init?(letter: String) {
        guard let match = Move.allCases.first(where: { $0.rawValue.first == letter.lowercased().first }) else { return nil }
        self = match
    }
}

var you = 0, computer = 0
while you < 3 && computer < 3 {
    print("rock, paper or scissors (r/p/s)? ", terminator: "")
    guard let line = readLine() else { print("\nBye!"); exit(0) }
    guard let mine = Move(letter: line) else { print("Type r, p or s."); continue }
    let theirs = Move.allCases.randomElement()!
    let result: String
    if mine == theirs {
        result = "Draw."
    } else if mine.beats == theirs {
        you += 1
        result = "You win the round!"
    } else {
        computer += 1
        result = "Computer wins the round."
    }
    print("You: \(mine.rawValue)  Computer: \(theirs.rawValue)  →  \(result)  [\(you)-\(computer)]")
}
print(you > computer ? "🏆 You won the match!" : "Computer takes the match.")

