let words = ["swift", "mango", "keyboard", "function", "variable", "galaxy", "puzzle", "rhythm", "island", "rocket"]
let word = words.randomElement()!
var guessed = Set<Character>()
var lives = 6

func shown() -> String { word.map { guessed.contains($0) ? String($0) : "_" }.joined(separator: " ") }

while lives > 0 && !Set(word).isSubset(of: guessed) {
    let tried = guessed.sorted().map(String.init).joined(separator: " ")
    print("\n\(shown())   lives: \(String(repeating: "♥", count: lives))   tried: \(tried)")
    print("Letter: ", terminator: "")
    guard let line = readLine() else { print("\nThe word was \(word). Bye!"); exit(0) }
    guard line.count == 1, let letter = line.lowercased().first, letter.isLetter else {
        print("One letter, please.")
        continue
    }
    if guessed.contains(letter) {
        print("You tried that already.")
    } else {
        guessed.insert(letter)
        if !word.contains(letter) {
            lives -= 1
            print("Nope.")
        }
    }
}
print(lives > 0 ? "\nYou got it: \(word)! 🎉" : "\nOut of lives. The word was \(word).")

import Foundation
setvbuf(stdout, nil, _IONBF, 0)

let lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]

func winner(_ b: [Character]) -> Character? {
    for l in lines where b[l[0]] != " " && b[l[0]] == b[l[1]] && b[l[1]] == b[l[2]] { return b[l[0]] }
    return b.contains(" ") ? nil : "D"   // D = draw
}

func minimax(_ b: inout [Character], _ player: Character) -> (score: Int, move: Int) {
    if let w = winner(b) { return (w == "O" ? 1 : w == "X" ? -1 : 0, -1) }
    var best = (score: player == "O" ? -2 : 2, move: -1)
    for i in 0..<9 where b[i] == " " {
        b[i] = player
        let score = minimax(&b, player == "O" ? "X" : "O").score
        b[i] = " "
        if (player == "O" && score > best.score) || (player == "X" && score < best.score) { best = (score, i) }
    }
    return best
}

func draw(_ b: [Character]) {
    var rows: [String] = []
    for r in 0..<3 {
        var cells: [String] = []
        for c in 0..<3 {
            let i = r * 3 + c
            cells.append(b[i] == " " ? String(i + 1) : String(b[i]))
        }
        rows.append(cells.joined(separator: " | "))
    }
    print("\n" + rows.joined(separator: "\n---------\n") + "\n")
}

var board = [Character](repeating: " ", count: 9)
while winner(board) == nil {
    draw(board)
    print("Your move (1-9): ", terminator: "")
    guard let line = readLine() else { print("\nBye!"); exit(0) }
    guard let n = Int(line.trimmingCharacters(in: .whitespaces)), (1...9).contains(n), board[n - 1] == " " else {
        print("Pick an empty square.")
        continue
    }
    board[n - 1] = "X"
    if winner(board) == nil { board[minimax(&board, "O").move] = "O" }
}
draw(board)
switch winner(board) {
case "X": print("You win?! That shouldn't happen.")
case "O": print("Computer wins.")
default: print("It's a draw.")
}

