struct Roll {
    let dice: [Int]
    let bonus: Int
    var total: Int { dice.reduce(0, +) + bonus }
}

/// Understands "2d6", "d20+5" and "4d8-1".
func roll(_ text: String) -> Roll? {
    let t = text.lowercased().replacingOccurrences(of: " ", with: "")
    let parts = t.split(separator: "d", maxSplits: 1, omittingEmptySubsequences: false)
    guard parts.count == 2 else { return nil }
    let count = parts[0].isEmpty ? 1 : Int(parts[0]) ?? 0
    var sidesText = String(parts[1]), bonus = 0
    if let i = sidesText.firstIndex(where: { $0 == "+" || $0 == "-" }) {
        bonus = Int(sidesText[i...]) ?? 0
        sidesText = String(sidesText[..<i])
    }
    guard let sides = Int(sidesText), (1...100).contains(count), (2...1000).contains(sides) else { return nil }
    return Roll(dice: (0..<count).map { _ in Int.random(in: 1...sides) }, bonus: bonus)
}

for sample in ["2d6", "d20+5", "4d8-1"] {
    if let r = roll(sample) { print("\(sample): \(r.dice) = \(r.total)") }
}
print("Roll dice (like 2d6 or d20+5). q to quit.")
while true {
    print("> ", terminator: "")
    guard let line = readLine(), line != "q", !line.isEmpty else { break }
    if let r = roll(line) { print("\(r.dice) = \(r.total)") } else { print("Write dice like 2d6 or d20+5.") }
}

