struct Room {
    let text: String
    var exits: [String: String] = [:]
    var item: String? = nil
    var locked: String? = nil
    var isEnd = false
}

var rooms: [String: Room] = [
    "hall": Room(text: "A dusty hall. Doors lead north and east.", exits: ["north": "library", "east": "kitchen"]),
    "library": Room(text: "Shelves of old books. A brass key glints on a desk.", exits: ["south": "hall"], item: "key"),
    "kitchen": Room(text: "A cold kitchen. A locked door leads north.", exits: ["west": "hall", "north": "garden"], locked: "north"),
    "garden": Room(text: "Sunlight! You made it outside. 🌳", isEnd: true),
]

var current = "hall"
var bag = Set<String>()
print("Commands: north, south, east, west, take, bag, quit")

while true {
    let here = rooms[current]!
    print("\n" + here.text)
    if here.isEnd { break }
    print("> ", terminator: "")
    guard let command = readLine()?.lowercased().trimmingCharacters(in: .whitespaces), command != "quit" else { break }
    switch command {
    case "bag":
        print("You carry: " + (bag.isEmpty ? "nothing" : bag.sorted().joined(separator: ", ")))
    case "take":
        if let item = here.item {
            bag.insert(item)
            rooms[current]!.item = nil
            print("Taken.")
        } else {
            print("Nothing to take here.")
        }
    default:
        if let next = here.exits[command] {
            if here.locked == command && !bag.contains("key") {
                print("The door is locked.")
            } else {
                current = next
            }
        } else {
            print("You can't do that here.")
        }
    }
}

