let words = ["apple", "brick", "crane", "drive", "eagle", "flame", "grape", "house", "juice", "knife",
             "lemon", "mango", "night", "ocean", "piano", "queen", "river", "stone", "tiger", "water"]

func score(_ guess: String, against answer: String) -> String {
    let g = Array(guess), a = Array(answer)
    var marks = [String](repeating: "⬛", count: 5)
    var left: [Character?] = a
    for i in 0..<5 where g[i] == a[i] {
        marks[i] = "🟩"
        left[i] = nil
    }
    for i in 0..<5 where marks[i] == "⬛" {
        if let j = left.firstIndex(of: g[i]) {
            marks[i] = "🟨"
            left[j] = nil
        }
    }
    return marks.joined()
}

let answer = words.randomElement()!
var solved = false
var turn = 1
while turn <= 6 && !solved {
    print("Guess \(turn)/6: ", terminator: "")
    guard let line = readLine() else { break }
    let guess = line.lowercased().trimmingCharacters(in: .whitespaces)
    guard guess.count == 5, guess.allSatisfy({ $0.isLetter }) else {
        print("Five letters, please.")
        continue
    }
    print("\(score(guess, against: answer)) \(guess.uppercased())")
    solved = guess == answer
    turn += 1
}
print(solved ? "You got it! 🎉" : "The word was \(answer.uppercased()).")

