struct Todo: Codable {
    var text: String
    var done = false
}

let file = URL(fileURLWithPath: "todos.json")

func load() -> [Todo] {
    guard let data = try? Data(contentsOf: file), let saved = try? JSONDecoder().decode([Todo].self, from: data) else {
        return [Todo(text: "Try the add command"), Todo(text: "Read this code", done: true)]
    }
    return saved
}

func save(_ todos: [Todo]) {
    if let data = try? JSONEncoder().encode(todos) { try? data.write(to: file) }
}

func show(_ todos: [Todo]) {
    print("")
    if todos.isEmpty { print("Nothing to do. 🎉") }
    for (i, t) in todos.enumerated() { print("\(i + 1). [\(t.done ? "x" : " ")] \(t.text)") }
}

var todos = load()
print("Commands: add <task>, done <number>, remove <number>, quit")
while true {
    show(todos)
    print("> ", terminator: "")
    guard let line = readLine(), !line.isEmpty, line != "quit" else { break }
    let parts = line.split(separator: " ", maxSplits: 1).map(String.init)
    let rest = parts.count > 1 ? parts[1] : ""
    switch parts[0] {
    case "add" where !rest.isEmpty:
        todos.append(Todo(text: rest))
    case "done", "remove":
        guard let n = Int(rest), todos.indices.contains(n - 1) else { print("Which number?"); continue }
        if parts[0] == "done" { todos[n - 1].done = true } else { todos.remove(at: n - 1) }
    default:
        print("Try: add Buy milk")
        continue
    }
    save(todos)
}

import Foundation
setvbuf(stdout, nil, _IONBF, 0)

let lower = Array("abcdefghijklmnopqrstuvwxyz")
let upper = Array("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
let digits = Array("0123456789")
let symbols = Array("!@#$%^&*-_")
let wordList = ["mango", "river", "cloud", "tiger", "piano", "lemon", "rocket", "forest", "ember", "comet", "maple", "otter"]

// SystemRandomNumberGenerator is cryptographically secure, so these are safe to use.
func password(length: Int = 16, useSymbols: Bool = true) -> String {
    let sets = [lower, upper, digits] + (useSymbols ? [symbols] : [])
    let all = sets.flatMap { $0 }
    var chars = sets.map { $0.randomElement()! }          // at least one of each kind
    while chars.count < length { chars.append(all.randomElement()!) }
    return String(chars.shuffled())
}

func passphrase(words: Int = 4) -> String {
    (0..<words).map { _ in wordList.randomElement()! }.joined(separator: "-") + String(Int.random(in: 10...99))
}

func strength(_ pw: String) -> String {
    var pool = 0
    if pw.contains(where: { $0.isLowercase }) { pool += 26 }
    if pw.contains(where: { $0.isUppercase }) { pool += 26 }
    if pw.contains(where: { $0.isNumber }) { pool += 10 }
    if pw.contains(where: { !$0.isLetter && !$0.isNumber }) { pool += 20 }
    let bits = Int(Double(pw.count) * log2(Double(max(pool, 1))))
    return "\(bits) bits, " + (bits < 40 ? "weak" : bits < 70 ? "okay" : "strong")
}

print("Passwords:")
for _ in 0..<3 { let pw = password(); print("  \(pw)  (\(strength(pw)))") }
print("Passphrases (easier to remember):")
for _ in 0..<3 { let pw = passphrase(); print("  \(pw)  (\(strength(pw)))") }
print("\nLength for a custom one [20]: ", terminator: "")
let length = Int(readLine()?.trimmingCharacters(in: .whitespaces) ?? "") ?? 20
print(password(length: min(max(length, 6), 128)))

