// Each unit is stored as "how many base units".
let tables: [[String: Double]] = [
    ["mm": 0.001, "cm": 0.01, "m": 1, "km": 1000, "in": 0.0254, "ft": 0.3048, "yd": 0.9144, "mi": 1609.344],
    ["g": 1, "kg": 1000, "oz": 28.3495, "lb": 453.592],
    ["ml": 1, "l": 1000, "cup": 236.588, "gal": 3785.41],
]

func convert(_ value: Double, from: String, to: String) -> Double? {
    for table in tables {
        if let a = table[from], let b = table[to] { return value * a / b }
    }
    return nil
}

func answer(_ text: String) -> String {
    let parts = text.lowercased().split(separator: " ").map(String.init)
    guard parts.count >= 3, let value = Double(parts[0]), let last = parts.last else { return "Write it like: 5 km to mi" }
    guard let result = convert(value, from: parts[1], to: last) else { return "Can't convert \(parts[1]) to \(last)." }
    return "\(parts[0]) \(parts[1]) = \(String(format: "%.4g", result)) \(last)"
}

for sample in ["5 km to mi", "150 lb to kg", "3 kg to km"] { print(answer(sample)) }
print("Units: " + tables.flatMap { $0.keys.sorted() }.joined(separator: ", "))
while true {
    print("> ", terminator: "")
    guard let line = readLine(), line != "q", !line.isEmpty else { break }
    print(answer(line))
}

