let common: Set<String> = ["the", "a", "an", "and", "is", "it", "to", "of", "like", "many"]

func analyze(_ text: String) {
    let words = text.lowercased()
        .components(separatedBy: CharacterSet.letters.inverted)
        .filter { !$0.isEmpty }
    let sentences = text.components(separatedBy: CharacterSet(charactersIn: ".!?"))
        .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
    var counts: [String: Int] = [:]
    for w in words where !common.contains(w) { counts[w, default: 0] += 1 }
    let top = counts.sorted { $0.value != $1.value ? $0.value > $1.value : $0.key < $1.key }.prefix(5)
    let letters = words.reduce(0) { $0 + $1.count }

    print("Characters:      \(text.count)")
    print("Words:           \(words.count)")
    print("Sentences:       \(sentences.count)")
    print("Avg word length: " + String(format: "%.1f", Double(letters) / Double(max(words.count, 1))))
    print("Reading time:    \(max(1, words.count * 60 / 200)) seconds")
    print("Longest word:    \(words.max { $0.count < $1.count } ?? "")")
    print("Top words:       " + top.map { "\($0.key) (\($0.value))" }.joined(separator: ", "))
}

