func shift(_ text: String, by key: Int) -> String {
    String(text.unicodeScalars.map { scalar -> Character in
        let base: UInt32
        switch scalar.value {
        case 65...90: base = 65
        case 97...122: base = 97
        default: return Character(scalar)
        }
        let moved = (Int(scalar.value - base) + key % 26 + 26) % 26
        return Character(UnicodeScalar(base + UInt32(moved))!)
    })
}

/// Try all 26 keys and keep the one whose result looks most like English.
func crack(_ secret: String) -> Int {
    let commonLetters = Set("etaoinshr")
    return (0..<26).max { a, b in
        let scoreA = shift(secret, by: -a).lowercased().filter { commonLetters.contains($0) }.count
        let scoreB = shift(secret, by: -b).lowercased().filter { commonLetters.contains($0) }.count
        return scoreA < scoreB
    } ?? 0
}

