let table: [(value: Int, symbol: String)] = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
    (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

func toRoman(_ number: Int) -> String? {
    guard (1...3999).contains(number) else { return nil }
    var n = number, out = ""
    for (value, symbol) in table {
        while n >= value {
            out += symbol
            n -= value
        }
    }
    return out
}

func fromRoman(_ text: String) -> Int? {
    var rest = Substring(text.uppercased()), total = 0
    for (value, symbol) in table {
        while rest.hasPrefix(symbol) {
            total += value
            rest = rest.dropFirst(symbol.count)
        }
    }
    // Reject things like IIII by checking the round trip.
    return rest.isEmpty && toRoman(total) == text.uppercased() ? total : nil
}

func convert(_ item: String) -> String {
    if let n = Int(item) { return toRoman(n) ?? "use 1 to 3999" }
    return fromRoman(item).map(String.init) ?? "not a valid Roman numeral"
}

